import math

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r == 1 or r == n-1:
        return n
    if r == 2:
        return n * (n - 1) // 2
    if r == 3:
        return n * (n - 1) * (n - 2) // 6
    if r == 4:
        return n * (n - 1) * (n - 2) * (n - 3) // 24
    return 0

def ratio_kn(n):
    if n < 4:
        return 0.0
    g = nCr(n, 4)
    f = nCr(n, 3)
    if f == 0:
        return 0.0
    return (g**3) / (f**4)

