def calculate_ratio(n):
    if n < 4:
        return 0
    f_G = comb(n, 3)
    g_G = comb(n, 4)

    if f_G == 0:
        # Should not happen for n >= 3
        return float('inf') 

    return (g_G**3) / (f_G**4)

