import math

def R(n):
    if n < 4:
        # R(3) = 0 since C(3, 4) = 0
        return 0.0

    try:
        comb_n_4 = math.comb(n, 4)
        comb_n_3 = math.comb(n, 3)

        # Ensure we don't divide by zero, though comb_n_3 > 0 for n >= 3
        if comb_n_3 == 0:
             return float('inf')

        numerator = comb_n_4**3
        denominator = comb_n_3**4
        return numerator / denominator
    except AttributeError:
        # Fallback for older Python versions without math.comb
        def combinations(n, k):
            if k < 0 or k > n:
                return 0
            if k == 0 or k == n:
                return 1
            if k > n // 2:
                k = n - k
            res = 1
            for i in range(k):
                res = res * (n - i) // (i + 1)
            return res

        comb_n_4 = combinations(n, 4)
        comb_n_3 = combinations(n, 3)

        if comb_n_3 == 0:
             return float('inf')

        numerator = comb_n_4**3
        denominator = comb_n_3**4
        return numerator / denominator

# Test sequence up to n=20
results = {}
is_increasing = True
previous_R = -1.0

for n in range(3, 21):
    current_R = R(n)
    results[n] = current_R

    if n >= 4:
